{
  "a_sentences": [
    {
      "a_text": "Le litige porte sur le droit d'accès aux données personnelles de la personne assurée au sens des art. 25 ss LPD.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le responsable du traitement peut refuser ou restreindre la communication des renseignements lorsque les intérêts prépondérants d'un tiers l'exigent ou lorsque les intérêts prépondérants de la personne privée, responsable du traitement, l'exigent et que celle-ci ne communique pas les données à un tiers.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le droit d'accès prévu à l'art. 25 LPD permet à toute personne de demander si des données la concernant sont traitées et de recevoir les informations nécessaires pour faire valoir ses droits et garantir la transparence du traitement, notamment les données personnelles traitées et la finalité du traitement.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le droit d'accès est inconditionnel et un intérêt à la consultation n'a en principe pas à être prouvé.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le raisonnement de la juridiction cantonale ne prête pas le flanc à la critique.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que la cour cantonale a donné accès à la personne assurée à l'information sur le but de l'enquête et à certains passages de la synthèse concernant le professeur personnellement ainsi qu'aux conclusions finales.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le refus de communiquer les parties IV et V du rapport d'audit de climat ne viole pas le droit d'accès de la personne assurée à ses données personnelles.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Les autres paragraphes de la synthèse ne comprennent pas de données personnelles de la personne assurée.",
      "b_propositions": ["P8"]
    }
  ]
}
